@RunWith(AndroidJUnit4.class)
public class AndroidShareTest {
 Context target,fixtures;
 @Before public void setup(){target=InstrumentationRegistry.getInstrumentation().getTargetContext();fixtures=InstrumentationRegistry.getInstrumentation().getContext();IncomingStore.erase(new File(target.getFilesDir(),"incoming"));IncomingStore.erase(new File(target.getCacheDir(),"exports"));}
 Uri fixture(String name,boolean pdf)throws Exception{android.os.Bundle args=new android.os.Bundle();args.putBoolean("pdf",pdf);android.os.Bundle result=target.getContentResolver().call(Uri.parse("content://dev.waraqa.android.test.fixtures"),"create",name,args);assertNotNull(result);Uri uri=Uri.parse(result.getString("uri"));assertEquals("External fixture read grant",PackageManager.PERMISSION_GRANTED,target.checkUriPermission(uri,android.os.Process.myPid(),android.os.Process.myUid(),Intent.FLAG_GRANT_READ_URI_PERMISSION));try(InputStream stream=target.getContentResolver().openInputStream(uri)){assertNotNull(stream);assertTrue(stream.read()!=-1);}return uri;}
 Intent incoming(String action,Uri... uris){Intent intent=new Intent(target,MainActivity.class).setAction(action).setType(uris.length>1?"*/*":"application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(uris.length>1)intent.putParcelableArrayListExtra(Intent.EXTRA_STREAM,new ArrayList<>(Arrays.asList(uris)));else intent.putExtra(Intent.EXTRA_STREAM,uris[0]);ClipData clip=ClipData.newRawUri("shared",uris[0]);for(int i=1;i<uris.length;i++)clip.addItem(new ClipData.Item(uris[i]));intent.setClipData(clip);return intent;}
 JSONObject waitBatch()throws Exception{for(int i=0;i<150;i++){JSONArray list=new IncomingStore(target).list();if(list.length()>0)return list.getJSONObject(0);Thread.sleep(100);}throw new AssertionError("Native share never reached inbox");}
 String harnessId;
 void harness(ActivityScenario<MainActivity> scenario){harnessId=UUID.randomUUID().toString();String id=harnessId;scenario.onActivity(a->{a.web.stopLoading();String html="<html><body><p id='result'>native-test</p><script>window.testHarnessId="+JSONObject.quote(id)+";window.replies={};WaraqaAndroid.onmessage=e=>{const m=JSON.parse(e.data);window.replies[m.requestId]=m;};window.callNative=m=>WaraqaAndroid.postMessage(JSON.stringify(m));</script></body></html>";byte[] bytes=html.getBytes(java.nio.charset.StandardCharsets.UTF_8);a.web.setWebViewClient(new android.webkit.WebViewClient(){@Override public android.webkit.WebResourceResponse shouldInterceptRequest(android.webkit.WebView view,android.webkit.WebResourceRequest request){if(request.getUrl().getPath().equals("/waraqa/android-native-test/"))return new android.webkit.WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(bytes));return super.shouldInterceptRequest(view,request);}});android.webkit.ServiceWorkerController.getInstance().setServiceWorkerClient(new android.webkit.ServiceWorkerClient(){@Override public android.webkit.WebResourceResponse shouldInterceptRequest(android.webkit.WebResourceRequest request){if(request.getUrl().getPath().equals("/waraqa/android-native-test/"))return new android.webkit.WebResourceResponse("text/html","UTF-8",new ByteArrayInputStream(bytes));return null;}});a.web.setWebChromeClient(new android.webkit.WebChromeClient(){@Override public boolean onConsoleMessage(android.webkit.ConsoleMessage m){android.util.Log.i("WaraqaTest",m.message());return true;}});a.web.loadUrl(MainActivity.HOME+"android-native-test/?case="+id);});}

 String eval(ActivityScenario<MainActivity> scenario,String script)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> result=new AtomicReference<>();scenario.onActivity(a->a.web.evaluateJavascript(script,v->{result.set(v);latch.countDown();}));assertTrue(latch.await(10,TimeUnit.SECONDS));return result.get();}
 JSONObject request(ActivityScenario<MainActivity> scenario,JSONObject message)throws Exception{String id=UUID.randomUUID().toString();message.put("requestId",id);for(int i=0;i<100;i++){if("true".equals(eval(scenario,"document.readyState==='complete'&&window.testHarnessId==="+JSONObject.quote(harnessId)+"&&typeof window.callNative==='function'")))break;Thread.sleep(100);}eval(scenario,"window.callNative("+message+")");for(int i=0;i<150;i++){String result=eval(scenario,"JSON.stringify(window.replies["+JSONObject.quote(id)+"]||null)");Object text=new JSONTokener(result).nextValue();if(text instanceof String&&!text.equals("null"))return new JSONObject((String)text);Thread.sleep(100);}throw new AssertionError("Bridge timed out: "+message+" state="+eval(scenario,"JSON.stringify({url:location.href,ready:document.readyState,harness:window.testHarnessId,replies:window.replies})"));}
 JSONObject msg(String action)throws Exception{return new JSONObject().put("action",action);}
 @Test public void androidRegistersAllShareFilters(){for(String action:new String[]{Intent.ACTION_SEND,Intent.ACTION_SEND_MULTIPLE})for(String type:new String[]{"image/png","image/jpeg","application/pdf","application/octet-stream"}){Intent intent=new Intent(action).setType(type).setPackage(target.getPackageName()).addCategory(Intent.CATEGORY_DEFAULT);List<ResolveInfo> matches=target.getPackageManager().queryIntentActivities(intent,PackageManager.MATCH_DEFAULT_ONLY);assertTrue(action+" "+type,matches.stream().anyMatch(r->r.activityInfo.name.equals(MainActivity.class.getName())));}assertTrue(target.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_SEND).setType("text/plain").setPackage(target.getPackageName()),PackageManager.MATCH_DEFAULT_ONLY).isEmpty());assertFalse(MainActivity.trusted(Uri.parse("https://example.com/waraqa/")));assertFalse(MainActivity.trusted(Uri.parse("http://dr-askar.github.io/waraqa/")));assertFalse(MainActivity.trusted(Uri.parse("https://dr-askar.github.io/other/")));}
 @Test public void receivesMultipleImagesAndPdfThroughNativeBridge()throws Exception{try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(incoming(Intent.ACTION_SEND_MULTIPLE,fixture("one.png",false),fixture("two.png",false),fixture("فاتورة.pdf",true)))){JSONObject batch=waitBatch();assertEquals(3,batch.getJSONArray("files").length());InstrumentationRegistry.getInstrumentation().waitForIdleSync();harness(scenario);assertTrue(request(scenario,msg("hello")).getBoolean("ok"));JSONObject response=request(scenario,msg("list"));assertEquals(3,response.getJSONArray("value").getJSONObject(0).getJSONArray("files").length());JSONObject file=batch.getJSONArray("files").getJSONObject(0);JSONObject read=request(scenario,msg("read").put("batchId",batch.getString("id")).put("fileId",file.getString("id")).put("offset",0).put("length",8));assertArrayEquals(new byte[]{(byte)137,80,78,71,13,10,26,10},Base64.decode(read.getString("value"),Base64.DEFAULT));JSONObject invalid=request(scenario,msg("read").put("batchId",batch.getString("id")).put("fileId","../../private").put("offset",0).put("length",8));assertFalse(invalid.getBoolean("ok"));request(scenario,msg("delete").put("batchId",batch.getString("id")));assertEquals(0,new IncomingStore(target).list().length());}}
 @Test public void pendingPdfSurvivesApplicationRestart()throws Exception{String id;try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(incoming(Intent.ACTION_SEND,fixture("single.pdf",true)))){id=waitBatch().getString("id");}try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(new Intent(target,MainActivity.class))){assertEquals("application/pdf",new IncomingStore(target).get(id).getJSONArray("files").getJSONObject(0).getString("type"));harness(scenario);assertTrue(request(scenario,msg("hello")).getBoolean("ok"));}}
 @Test public void exportsFileToAndroidShareAndStoragePicker()throws Exception{Intents.init();try{intending(hasAction(Intent.ACTION_CHOOSER)).respondWith(new ActivityResult(Activity.RESULT_CANCELED,null));Uri destination=fixture("saved.pdf",true);Intent result=new Intent().setData(destination).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);intending(hasAction(Intent.ACTION_CREATE_DOCUMENT)).respondWith(new ActivityResult(Activity.RESULT_OK,result));try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(new Intent(target,MainActivity.class))){harness(scenario);for(String mode:new String[]{"share","save"}){byte[] bytes=("PDF bytes "+mode).getBytes(java.nio.charset.StandardCharsets.UTF_8);JSONObject begin=request(scenario,msg("beginExport").put("name","تصدير.pdf").put("type","application/pdf").put("size",bytes.length));String token=begin.getString("value");assertTrue(request(scenario,msg("writeExport").put("token",token).put("offset",0).put("data",Base64.encodeToString(bytes,Base64.NO_WRAP))).getBoolean("ok"));assertTrue(request(scenario,msg("finishExport").put("token",token).put("mode",mode)).getBoolean("ok"));if(mode.equals("save")){try(InputStream stream=target.getContentResolver().openInputStream(destination)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] chunk=new byte[128];int n;while((n=stream.read(chunk))!=-1)out.write(chunk,0,n);assertArrayEquals(bytes,out.toByteArray());}}}intended(hasAction(Intent.ACTION_CHOOSER));intended(hasAction(Intent.ACTION_CREATE_DOCUMENT));}}finally{Intents.release();}}
 String evaluate(ActivityScenario<MainActivity> scenario,String expression)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> out=new AtomicReference<>();scenario.onActivity(a->a.web.evaluateJavascript(expression,v->{out.set(v);latch.countDown();}));assertTrue(latch.await(10,TimeUnit.SECONDS));return out.get();}
 @Test public void nativeNotificationsHaveSixDistinctSafeActionsAndPreserveWarmPage()throws Exception{
  if(android.os.Build.VERSION.SDK_INT>=33){try(android.os.ParcelFileDescriptor fd=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand("pm grant "+target.getPackageName()+" android.permission.POST_NOTIFICATIONS");InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] buf=new byte[1024];while(in.read(buf)!=-1){}}}
  try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(new Intent(target,MainActivity.class))){harness(scenario);assertTrue(request(scenario,msg("hello")).getJSONObject("value").getBoolean("notificationShortcuts"));JSONObject enabled=request(scenario,msg("notificationShortcuts").put("enabled",true));assertTrue(enabled.toString(),enabled.getBoolean("ok"));assertTrue(enabled.getJSONObject("value").getBoolean("enabled"));android.app.NotificationManager manager=target.getSystemService(android.app.NotificationManager.class);
   java.util.Set<String> intents=new java.util.HashSet<>();int actionCount=0;for(android.service.notification.StatusBarNotification entry:manager.getActiveNotifications()){if(entry.getId()!=NotificationShortcuts.CAPTURE&&entry.getId()!=NotificationShortcuts.EDIT)continue;android.app.Notification notification=entry.getNotification();assertEquals(3,notification.actions.length);assertEquals(android.app.Notification.VISIBILITY_PRIVATE,notification.visibility);for(android.app.Notification.Action action:notification.actions){actionCount++;if(android.os.Build.VERSION.SDK_INT>=31)assertTrue(action.actionIntent.isImmutable());assertEquals(target.getPackageName(),action.actionIntent.getCreatorPackage());intents.add(action.title.toString());}}
   assertEquals(6,actionCount);assertEquals(6,intents.size());evaluate(scenario,"window.waraqaNativeShortcut=tool=>{window.__shortcut=tool};true");AtomicReference<String> before=new AtomicReference<>();scenario.onActivity(a->before.set(a.web.getUrl()));
   for(String tool:new String[]{"scan","ocr","id","book","signature","tools"}){NotificationShortcuts.pending(target,tool).send();String observed="";for(int i=0;i<30;i++){observed=evaluate(scenario,"window.__shortcut||''");if(observed.equals(JSONObject.quote(tool)))break;Thread.sleep(100);}assertEquals(JSONObject.quote(tool),observed);scenario.onActivity(a->assertEquals(before.get(),a.web.getUrl()));}
   assertFalse(NotificationShortcuts.validTool("file:///private"));assertTrue(request(scenario,msg("notificationShortcuts").put("enabled",false)).getBoolean("ok"));assertFalse(NotificationShortcuts.selected(target));boolean gone=false;for(int i=0;i<50;i++){boolean present=false;for(android.service.notification.StatusBarNotification entry:manager.getActiveNotifications())if(entry.getId()==NotificationShortcuts.CAPTURE||entry.getId()==NotificationShortcuts.EDIT||entry.getId()==NotificationShortcuts.SUMMARY)present=true;if(!present){gone=true;break;}Thread.sleep(100);}assertTrue("Native shortcut panels were not cancelled",gone);
  }finally{NotificationShortcuts.configure(target,false);}
 }
 @Test public void shortcutColdStartUsesOnlyAllowlistedTools()throws Exception{try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(NotificationShortcuts.intent(target,"book"))){AtomicReference<String> address=new AtomicReference<>();for(int i=0;i<40;i++){scenario.onActivity(a->address.set(a.web.getUrl()));if(address.get()!=null)break;Thread.sleep(100);}assertNotNull(address.get());assertEquals("book",android.net.Uri.parse(address.get()).getQueryParameter("tool"));}try{NotificationShortcuts.intent(target,"../../private");fail("Invalid shortcut accepted");}catch(IllegalArgumentException expected){}}

}
